INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Сабозу тӯбулӣ: Ташхиси истифодаи самараноки об ва таъсири он ба сифати маҳсулоти кишоварзӣ (Бо назардошти усулҳои муосир)' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Ба таҳлили таъсири сабозу тӯбулӣ (AFD/AFB) ба сифати маҳсулот диққат диҳед. Ин роҳномаи стратегӣ усулҳои муосирро барои самаранок кардани истифодаи об, кам кардани сарфа ва баланд бардоштани хосиятҳои физикӣ ва химиявии меваово ва сабзавотҳо муайян мекунад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
