INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعلّم كيف تدمج وحدة التحكم المنطقية البرمجية (PLC) في نظام الري بالتنقيط لزيادة الكفاءة وتقليل الهدر. دليل عملي تفصيلي يركز على التقنيات المتقدمة لإدارة المياه بدقة لخدمة المزارع العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
