INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Ин мақола раҳбарии пурра барои автоматизатсияи тасмаи конвейерро овардааст. Дар ин ҷо чӣ тавр таймерҳоро танзим кардан мумкин аст, чӣ тавр сенсорҳои намӣро истифода бурдан мумкин аст. Барои корҳои кишоварзӣ муҳим аст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
