INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعلّم كيف يقلل توتشيح نيتي (Stress) في المزروعات من خلال استخدام تقنية شريط تيبي (Teip) لري استراتيجي. دليل وافٍ للمزارعين العراقيين لتحسين كفاءة الماء وضمان نمو النباتات.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
