INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','حساب الاحتياج المائي للنباتات عبر ET0: الري بالتنقيط والشريطي' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كيفية حساب الاحتياج المائي للنباتات باستخدام ET0 مع التركيز على طرق الري بالتنقيط والري الشريطي. دليل شامل للمزارعين لتحسين كفاءة استخدام المياه.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
