INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','راهنمای کاملی برای کشاورزان و متصدیان بازار در ایران برای مقایسه برندهای مختلف نوار تیپ (Tippy Tape) و انتخاب محصول مناسب بر اساس کیفیت، دوام و کاربرد. شامل نکات فنی و توصیه‌های عملی برای استفاده بهینه در مزارع.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
