INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола бренди бартарин наварҳои TPO (наварҳои полипропилен) барои сабзоткунии боғзор муқоиса карда мешаванд. Донишҳои техникӣ ва мустаҳкамӣ нишон дода шуда, имконияти фарогирии наварҳои босифатро татбиқ намудан ва хориҷ бароҳамии бозорро таъмин карданро омӯзед.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
