INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Хулосаи мухтасари оянда ва истифодабарии обии ҳосилнокӣ: Раҳнамои тавозунии тӯлонӣ барои банд кардани ҳосилнокии. Истифодаи технологияҳои навин ва тактикаҳои барои деҳқон.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
