INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро фосилаи қаторҳо дар интихоби қатрапош ҳатмист?</h2>\n<p>Яке аз саволҳои такроршудаи муҳандисони кишоварзӣ ва боғдорон, <strong>интихоби қатрапош бар асоси фосилаи қаторҳо</strong> аст. Ин мавзӯъ ба таври мустақим ба якҳамвории обёрӣ, фишори корӣ дар система ва дар натиҷа ба хароҷоти сармоягузорӣ таъсир мерасонад. Агар фосилаи қаторҳои карорат бо вазнииш ва дарозии нории тиб ё қатрапошҳои хаттӣ номувофиқ бошад, дар поёни лӯлак коҳиши ҳаҷми об (қубор), оғоз кардани ҷамъшавии об дар решаҳои амиқ ё хушкӣ дар қисмҳои миёнаи қаторро мебинем.</p>\n<p>Дар системаҳои обёрӣ бо қатрапош, оғози об бо фишори кам аз қатрапошҳо ба замин дар меравад. Бинобар ин, дарозии масири ҳаракати об аз оғози нории то поёни он бояд бо дақиқӣ тарҳрезӣ шавад, то камшавии фишор (Head Loss) дар ҳудуди ҷазо боқӣ монад. Фосила байни қаторҳо муайянкунандаи дарозии нуруиҳои мувози аст; ҳар чӣ фосилаи қаторҳо зиёдтар бошад, нуруиҳои бештар лозим мешавад ва дар натиҷа, ҷойгиркунии шабакаи асосӣ ва иловагӣ мураккабтар мегардад. Ба тарафдори, дар кароратҳои зич бо фосилаи кам байни қаторҳо, метавон аз нуруиҳои кӯтоҳтар ё қатрапошҳо бо фосилаи наздиктар истифода бурд.</p>\n\n\n\n<h2>Таъсири гурди барғидор дар интихоби вазнииши нории тиб</h2>\n<p>Барои интихоби дурусти қатрапош, аввал бояд гурди коробро (фосила байни хатҳо) муайян кунем. Гурдҳои маъмул дар кишоварзии Эрон аз 30 то 120 сантиметр фарқ мекунад. Ҳар яке аз ин гурдҳо ба маълумотҳои техникии гуногун дар нории тиб ниёз дорад:</p>\n<ul>\n<li><strong>Гурдҳои паст (30 то 50 сантиметр):</strong> Одатан барои парҳаҳои сабзӣ бо решаҳои сатҳӣ, монанди гӯлӯбӣ ё каду, мувофиқ аст. Дар ҳолати чунин истифодаи лентҳои бо калиди 10 ё 12 миллиметр ва масофаи бағдалкунандагони 10 то 20 сантиметрӣ тавсия дода мешавад, то намӣ дар минтачаи решагӣ маҳдуд боқӣ монад.</li>\n<li><strong>Парҳаҳои миёна (60 то 90 сантиметр):</strong> Барои бисёр маҳсулоти калон, монанди буғдолу ва мӯз, мувофиқ аст. Дар ин масофа, истифодаи калиди 15 ё 16 миллиметр имконпазир аст. Дарозии лента бояд чунин бошад, ки партофт фишор дар охирин қисм аз 10 фоизи ҳажми ғайрилоғик камтар бошад.</li>\n<li><strong>Парҳаҳои калон (100 сантиметр ва бештар):</strong> Дар боғҳои дарахтӣ ё парҳаҳои донаҳои кушод, масофаи қаторҳо зиёд аст. Дар ин ҷо истифодаи бағдалкунандагони бисёрманбаъа ё лентаҳои бо калиди калонтар (20 миллиметр ва бештар) бо ҳазмҳои интизорашаванда зарур аст. Инчунин, имкон дорад аз системҳои хаттӣ бо бағдалкунандаҳои пластикӣ пайвастшаванда истифода барад.</li>\n</ul>\n<p>Барои фаҳмиши беҳтар оид ба таъсири дарозии лента ба ҳазми хориҷ, метавонед ба роҳнамоии <a href="https://navar-abyari.ir/important-tips-drip-tape-irrigation/">нуқтаҳои муҳими обёрӣ лентӣ</a> муроҷиат кунед, ки тафсилоти дақиқтарро тавзеҳ додааст.</p>\n\n<h2>Иртиботи дарозии риштаи нории бо инкириши фишор ва сарфи об</h2>\n<p>Қонуни умумӣ дар ихтисири навъи тамға-тами ин аст, ки ҳар қадар риштаи нории дарозтар бошад, инкириши фишор меафзояд. Агар масофаи қаторҳо комил бошад, дарозии ришта ба масофаи қаторҳо баробар нест, балки дарозии ришта ба дарозии қатор баробар аст. Аммо масофаи қаторҳо муайян мекунад, ки дар ягон воҳиди сатҳ чанде ришта лозим аст. Ҳамагӣ, як нуқтаи муҳим мавҷуд аст: дар тарҳии система, мо одатан риштаро ба дарозии қатор бармегардонем (Ҳалқаӣ) ё ба шакли хаттӣ (Хаттӣ) меҷӯшем. Агар ба шакли хаттӣ бошад, дарозии ришта ба дарозии қатор вобаста аст. Аммо агар системаро асоси ҷамъшавии об тарҳ кунем, масофаи қаторҳо муайянкунии шумораи хатҳои зерин аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/انتخاب-قطرهچکان-بر-اساس-فاصله-ردیفها-تصویر-شاخص.webp" alt="انتخاب قطره‌چکان بر اساس فاصله ردیف‌ها - تصویر 1"/><figcaption>strategic irrigation guide</figcaption></figure>\n<p>Дар системаҳои тасмагии кушода (Кушода-охир), сарфи об дар анҷоми ришта аз оғози он камтар хоҳад буд. Барои тадҳири ин ноустиморӣ, метавон аз риштаҳо бо шӯъаи гуногун дар оғози қатор ва анҷоми қатор истифода бурд, ё системаро ба шакли ҳалқаӣ (Пӯшида-охир) тарҳ кард, ки дар он об аз ҳар ду сар ба ришта дохил мекунад. Интихоби байни ин ду роҳ низ ба масофаи қаторҳо ва андозаи замин вобаста аст. Дар заминҳои танӯк бо масофаи калони қаторҳо, системаи ҳалқаӣ метавонад дар насб мушкил бошад, аммо якунвохатии беҳтар мебошад.</p>\n\n\n\n<h2>Нуқтаҳои амалӣ барои насб аз рӯи масофаи қаторҳо</h2>\n<p>Дар пай, чанд нуқтаи амалӣ барои муҳандисон ва деҳқонон муҳим аст, ки бевосита бо масофаи кишт ва навъи тамға-чакан алоқаманд аст:</p>\n<ol>\n<li><strong>Ҳамравии сӯрохҳои тамға-чакан бо қатори баргашт:</strong> Муҳим аст, ки риштаи нории дақиқан дар миёнаи қатор ва дар чуқурии мувофиқ (одатан аз 15 то 20 сантиметр зери сатҳи замин барои киштони донаҳо ё ҳамҳадд бо решаҳои асосӣ) ҷой гирад. Агар масофаи қаторҳо 80 сантиметр бошад, марказии ришта ҳаётӣ аст, то об ба ҳамаи решаҳо расад.</li>\n<li><strong>Истифода аз филтри мувофиқ:</strong> Бо зиёд шудани дарозии умумии система (ки ба шумури ва фосилаи сатҳҳо вобаста аст), имконияти ворид шудани зарраҳои хамлшуда ба қатқонакҳо зиёд мешавад. Барои фосилаҳо, камтар аз 100 сантиметр, филтри 80-масш мувофиқ аст, аммо барои системаҳои калонтар бо фосилаҳои кӯл, истихроҷ кардани филтрасиҳо-ситҳои бо зиршаклӣ ё диский метавонад тавсия дода шавад.</li>\n<li><strong>Диққат ба ҳароси замин:</strong> Агар фосилаи сатҳҳо дар самти ҳароси замин бошад, паҳлуди поёнӣ ба сабаби градиенти замин мешавад. Дар ин шароит, бояд дории қатқонакҳоро чунин интихоб кунед, ки тафовути дорӣ дар болои ва поёни ҳарос камтар аз 5 фоиз бошад. Ин масъала аз фосилаи сатҳҳои амудии ҳарос (Cross slope) фарқ мекунад.</li>\n<li><strong>Оҳастан дарозии лентаро бар асоси диаметър:</strong> Ҷадвалҳои сохтории сохтмонандагон нишон медиҳанд, ки барои лентаи 10 миллиметрӣ, дарозии максимумӣ дар шароити паҳлуди поёнӣ 20 фоиз тақрибан 100 метр аст. Агар фосилаи сатҳҳои шумо боиси расидани дарозии сатҳи шаболигӣ ба 150 метр шавад, бояд ё диаметри лентаро ба 15 ё 16 миллиметр зиёд кунед ё лентаро шакли даврагӣ бо як ҳисобкунии миёна гузоред.</li>\n</ol>\n<p>Барои ошно шудан бо стандартҳои ҷамъоварии маҳсулоти гуногун, ки бевосита ба ниёз ба об ва тарҳрезии система вобаста аст, метавонед мақолаи миқдори ҷамъоварии гӯлустона дар гектарро таҳти назар гиред, зеро гӯлустона ба системаҳои обёрӣи дақиқ бо фосилаи сатҳҳои муайян эҳтиёз дорад.</p>\n\n<h2>Таъсири фосилаи сатҳҳо ба самаранокии истеҳсолӣ ва идоракунии система</h2>\n<p>Интихоби дурусти қатқонак бар асоси фосилаи сатҳҳо на танҳо як масъалаи муҳандисӣ, балки як масъалаи иқтисодӣ ва идоракунӣ аст. Дар фосилаҳои хеле кӯл (масалан, 30 сантиметр барои разиана), хараҷи лентаро барои ҳар гектар зиёдтар мешавад, зеро митражи зиёдтар аст. Дар нимаҳои дигар, дар фосилаҳои кӯл (120 сантиметр барои картошка), истиифодаи лентаро камтар аст, аммо дории ҳар як қатқонак бояд баландтар бошад, то ки пӯшиши кофӣ фароҳам оварда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/انتخاب-قطرهچکان-بر-اساس-فاصله-ردیفها-کاربرد-عملی.webp" alt="انتخاب قطره‌چکان بر اساس فاصله ردیف‌ها - تصویر 2"/><figcaption>strategic irrigation guide</figcaption></figure>\n<p>Ҳамчунин, нигоҳдории система дар масофаҳои зиёд мураккабтар аст. Хатоии як нуқта дар паҳлу чӯкандар аз саби дарозии паҳлу, метавонад боиси ихтисори об шудани қисмати калони сатҳи паҳлу гардад. Бинобар ин, дар масофаҳои зиёд, истифодаи чуқандарҳои пайвастшаванда (Connector Drips) ё паҳлуҳо бо имкони таъмيري осон ҳаяҷон мебошад. Барои маълумоти бештар дар бораи нигоҳдории дарозумр кардани ин системҳо, раҳнамоии <a href="https://navar-abyari.ir/mazaya-sharit-al-ray/">Дарозумр кардани паҳлу чуқандар</a> ро таҳқик намоед.</p>\n\n\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё масофаи паҳлуҳо барои интихоби дебит чуқандар муҳим аст?</h3>\n<p>Бале. Агар масофаи паҳлуҳо зиёд бошад, дебити ҳар як чуқандарро бояд зиёд кард, то намнокии кофӣ дар ҳудуди решаҳо таъмин шавад. Агар масофа кам бошад, дебити камтар ва масофаи наздиктари чуқандарҳо мувофиқ аст.</p>\n<h3>Чӣ гуна дарозии паҳлу чӯкандарро бар асоси масофаи паҳлуҳо ҳисоб кунам?</h3>\n<p>Дарозии паҳлу чӯкандар одатан вобаста ба дарозии паҳлу, на масофаи онҳо мебошад. Аммо масофаи паҳлуҳо муайянкунандаи шумораи паҳлуҳо дар ҳар гектар аст. Барои ҳисобкунии коҳиши фишор, дарозии паҳлу ва диаметри онро ба назар гиред, на масофаи паҳлуҳо, магар ин ки замин дарозимдуд бошад.</p>\n<h3>Оё барои партовҳои кушода (масалан, 150 см) аз намоди тейп истифода барем ё қатрапашиши хаттӣ?</h3>\n<p>Дар партовҳои кушода намоди тейп арзонтар ва тезтар насб мешавад, аммо умри хизматрасонии камтар дорад. Қатрапашиши хаттӣ бо лӯлаи PE 16 ё 20 мм умри хизматрасонии баландтар дорад ва барои киштҳои бо арзиши баланд, ба мисоли зафаранон ё доруӣ, ки партовҳои кушода доранд, мувофиқтар аст. Интихоби қатрапашиш дар ин ҳолат асосан ба ҳаҷми ҷараён ва фосилаи байни қатрапашишҳо вобаста аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/انتخاب-قطرهچکان-بر-اساس-فاصله-ردیفها-جزئیات-فنی.webp" alt="انتخاب قطره‌چکان بر اساس فاصله ردیف‌ها - تصویر 3"/><figcaption>strategic irrigation guide</figcaption></figure>\n<h3>Таъсири шадуди замин бар фосилаи силсилаҳо ва интихоби қатрапашиш чист?</h3>\n<p>Агар фосилаи силсилаҳо ба самти шадуд мувофиқат кунад, фишор дар поёни шадуд баландтар ва дар боло пасттар аст. Баёни асҳоли нақш: бояд аз қатрапашишҳои ҳассос ба фишор (Pressure Compensating) истифода бурд ё системаро чунин тарҳӣ кард, ки парҳези фишори аз ҷиҳати градиент ба вуҷудоянда ҷубур карда шавад.</p>\n\n<h2>Хулоса</h2>\n<p>Интихоби қатрапашиш асосан ба фосилаи силсилаҳо нигаронида шудан на танҳо харидани лӯла, балки як раванди муҳандисӣ мебошад, ки дорои мувозинат байни дарозии назар, диаметри лӯла, ҳаҷми ҷараён, фосилаи қатрапашишҳо ва шароити замин аст. Дар партовҳои хурд, дақиқӣ ва микронормативӣ муҳим аст; дар партовҳои калон, ҳаҷми ҷараён ва фарогирии об. Бо риояи қоидаҳо дар бандҳои ихтисосӣ ва амалӣ, метавон парҳези обро пешгирии кард ва самаранокии иқтисодии системаи обёрориро ба ҳадди аксар баррасид. Пеш аз харид, бо назардошти партои кишт, параметрҳои техникии намоди тейп ё қатрапашишро аз истеҳсолкунандаҳои боэътимод талаб кунед ва дар сурати лоязим, аз машварат бо ихтисосгарони обёрорӣ истифода баред.</p>\n<p>Барои тафаккури бештар дар бораи идоракунии намоди тейп аз пластикӣ барои обёрорӣ ва нуқтаҳои насби он, мо пешниҳод мекунем, ки раҳнамои Негар ба идоракунии обёрории тейп боварид.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%AF%D9%86%D8%AF%D9%85-%D8%A2%D8%A8%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DAAFD986D8AFD985 D8A2D8A8DB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>. <a href="https://navar-abyari.ir/basil-seed-quantity-per-hectare-farming-guide/">basil seed quantity per hectare farming guide</a></p>','Роҳнамои интихоби қутрачкан дар асоси фосилаи сафҳо: асосҳои нӯҳти тиб ва обёрӣи қутрагӣ','Фосилаи байни сатҳҳо, омили муҳим дар интихоби намуд ва хусусиятҳои системаи нафҳуршавӣ мебошад. Дар ин мақола мо робитаи байни фосилаи ниҳодани тохур, диаметри лӯла, суръат ва тӯли рӯйпӯши нӯрро таҳлил карда, нуқтаҳои амалӣ барои насби дурусти системаи нафҳуршавиро омӯзиш медиҳем.','publish','closed','closed','rahnamoyi-intikhib-i-qutrachkan-barasiasefa',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
